INSERT INTO `notification_logs` VALUES (20, 2, 2, 'App\\Events\\ChangeRequestCreated', '{\"cr_id\": 31227}', 'CR #2017 - Awaiting Your Approval', '<p>Dear Ahmed,</p>\n                <p>Change Request (CR) #2017 has been submitted and is waiting for your action.</p>\n                <p>Please use one of the buttons below to respond:</p>\n\n                <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin: 10px 0;\">\n                <tr>\n                    <td style=\"padding: 10px;\">\n                    <a href=\"mailto:mahmoud.bastawisy@te.eg?subject=Re%3A%20CR%20%232017%20-%20Awaiting%20Your%20Approval&cc=;Ticketing.DEV@te.eg&body=approved\" style=\"background-color: #28a745; color: #ffffff; padding: 12px 30px; text-decoration: none; border-radius: 5px; font-weight: bold; display: inline-block;\">✓ Approve</a>\n                    </td>\n                    <td style=\"padding: 10px;\">\n                    <a href=\"mailto:mahmoud.bastawisy@te.eg?subject=Re%3A%20CR%20%232017%20-%20Awaiting%20Your%20Approval&cc=;Ticketing.DEV@te.eg&body=rejected\" style=\"background-color: #dc3545; color: #ffffff; padding: 12px 30px; text-decoration: none; border-radius: 5px; font-weight: bold; display: inline-block;\">✗ Reject</a>\n                    </td>\n                    <td style=\"padding: 10px;\">\n                    <a href=\"https://10.20.24.82/index.php\" style=\"background-color: #007bff; color: #ffffff; padding: 12px 30px; text-decoration: none; border-radius: 5px; font-weight: bold; display: inline-block;\">View in TMS</a>\n                    </td>\n                </tr>\n                </table>\n\n                <p><i>To review this request directly in the TMS system, click \"View in TMS\" and select \"CRs Waiting Approval\".</i></p>\n\n                <hr>\n                <blockquote><p><b><font style=\"background-color: rgb(255, 0, 0);\" color=\"#ffffff\">Disclaimer</font>: </b>Kindly <b>avoid</b> using \"<b>Reply</b>,\" \"<b>Reply All</b>,\" or <b>forwarding</b> this email. Your action <b>will be lost</b> and not recorded if you do not use the buttons above.</p></blockquote>\n                <hr>\n                <p><b>Change Request Information:</b></p>\n                <ul>\n                <li><p><b>CR Subject:</b>&nbsp;CR Test</p></li>\n                <li><p><b>CR Description:</b>&nbsp;Test CR</p></li>\n                <li><p><b>Requester:</b> bi.admin</p></li>\n                </ul>\n                <p>Thank you in advance for your prompt action.</p>\n                <p>Best regards, TMS</p>\n                <p><i>Note: This is an automated message sent by the IT TMS System.</i></p>', '[\"ahmed.hammad@te.eg\"]', '[]', '[]', 'failed', 'Cannot send message without a sender address', NULL, 0, 'App\\Models\\Change_request', 31227, '2025-11-12 10:51:30', '2025-11-12 10:51:30');
