INSERT INTO `notification_logs` VALUES (256, 2, 2, 'App\\Events\\ChangeRequestCreated', '{\"cr_id\": 31287}', '[TMS] CR #6148 - Awaiting Your Approval', '<p>Dear Mohamed,</p>\r\n<p>Change Request (CR) #6148 has been submitted and is waiting for your action.</p>\r\n<p>Please use one of the buttons below to respond:</p>\r\n\r\n<table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin: 20px 0;\">\r\n  <tbody><tr>\r\n    <td style=\"padding: 10px;\">\r\n      <a href=\"mailto:ahmed.o.hasan@te.eg?subject=Re%3A%20CR%20%236148%20-%20Awaiting%20Your%20Approval&cc=;Ticketing.DEV@te.eg&body=approved\" style=\"background-color: #28a745; color: #ffffff; padding: 12px 30px; text-decoration: none; border-radius: 5px; font-weight: bold; display: inline-block;\">✓ Approve</a>\r\n    </td>\r\n    <td style=\"padding: 10px;\">\r\n      <a href=\"mailto:ahmed.o.hasan@te.eg?subject=Re%3A%20CR%20%236148%20-%20Awaiting%20Your%20Approval&cc=;Ticketing.DEV@te.eg&body=rejected\" style=\"background-color: #dc3545; color: #ffffff; padding: 12px 30px; text-decoration: none; border-radius: 5px; font-weight: bold; display: inline-block;\">✗ Reject</a>\r\n    </td>\r\n    <td style=\"padding: 10px;\">\r\n      <a href=\"https://10.20.24.82/index.php\" style=\"background-color: #007bff; color: #ffffff; padding: 12px 30px; text-decoration: none; border-radius: 5px; font-weight: bold; display: inline-block;\">View in TMS</a>\r\n    </td>\r\n  </tr>\r\n</tbody></table>\r\n\r\n<p><i>To review this request directly in the TMS system, click \"View in TMS\" and select \"CRs Waiting Approval\".</i></p>\r\n\r\n<hr>\r\n<blockquote><p><b><font style=\"background-color: rgb(255, 0, 0);\" color=\"#ffffff\">Disclaimer</font>: </b>Kindly <b>avoid</b> using \"<b>Reply</b>,\" \"<b>Reply All</b>,\" or <b>forwarding</b> this email. Your action <b>will be lost</b> and not recorded if you do not use the buttons above.</p></blockquote>\r\n<hr>\r\n<p><b>Change Request Information:</b></p>\r\n<ul>\r\n<li><p><b>CR Subject:</b>&nbsp;test20</p></li>\r\n<li><p><b>CR Description:</b>&nbsp;test</p></li>\r\n<li><p><b>Requester:</b> Mohamed.Behairy</p></li>\r\n</ul>\r\n<p>Thank you in advance for your prompt action.</p><hr><p><i><span style=\"font-weight: 600;\">Note:</span>&nbsp;This is an automated message sent by the IT TMS System.</i></p><p><span style=\"font-weight: 600;\">Best regards,</span><br><span style=\"font-weight: 600;\">TMS</span></p>', '[\"mohamed.behairy@te.eg\"]', '[]', '[\"ahmed.o.hasan@te.eg\"]', 'failed', 'Cannot send message without a sender address', NULL, 0, 'App\\Models\\Change_request', 31287, '2025-12-10 14:09:10', '2025-12-10 14:09:10');
