INSERT INTO `notification_templates` VALUES (1, 'CR Created - Notify Requester', '[TMS] CR #{{cr_no}} has been created', '<p>Dear {{first_name}},</p><p>Change Request (CR) #{{cr_no}} has been <b>created successfully</b>.</p><p><b>CR Title:</b> {{cr_title}}</p><p>You can review it here: <a href=\"{{cr_link}}\"><b>View CR #{{cr_no}}</b></a></p><hr><p><i><b>Note:</b> This is an automated message sent by the IT TMS System.</i></p><p><b>Best regards,</b><br><b>TMS</b></p>', '[\"cr_no\", \"first_name\", \"cr_link\"]', 1, '2025-10-30 20:42:59', '2025-11-13 11:40:21');
INSERT INTO `notification_templates` VALUES (2, 'CR Created - Notify Division Manager (Regular CR)', '[TMS] CR #{{cr_no}} - Awaiting Your Approval', '<p>Dear {{division_manager_name}},</p>\r\n<p>Change Request (CR) #{{cr_no}} has been submitted and is waiting for your action.</p>\r\n<p>Please use one of the buttons below to respond:</p>\r\n\r\n<table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"margin: 20px 0;\">\r\n  <tbody><tr>\r\n    <td style=\"padding: 10px;\">\r\n      <a href=\"{{approve_link}}\" style=\"background-color: #28a745; color: #ffffff; padding: 12px 30px; text-decoration: none; border-radius: 5px; font-weight: bold; display: inline-block;\">✓ Approve</a>\r\n    </td>\r\n    <td style=\"padding: 10px;\">\r\n      <a href=\"{{reject_link}}\" style=\"background-color: #dc3545; color: #ffffff; padding: 12px 30px; text-decoration: none; border-radius: 5px; font-weight: bold; display: inline-block;\">✗ Reject</a>\r\n    </td>\r\n    <td style=\"padding: 10px;\">\r\n      <a href=\"{{system_link}}\" style=\"background-color: #007bff; color: #ffffff; padding: 12px 30px; text-decoration: none; border-radius: 5px; font-weight: bold; display: inline-block;\">View in TMS</a>\r\n    </td>\r\n  </tr>\r\n</tbody></table>\r\n\r\n<p><i>To review this request directly in the TMS system, click \"View in TMS\" and select \"CRs Waiting Approval\".</i></p>\r\n\r\n<hr>\r\n<blockquote><p><b><font style=\"background-color: rgb(255, 0, 0);\" color=\"#ffffff\">Disclaimer</font>: </b>Kindly <b>avoid</b> using \"<b>Reply</b>,\" \"<b>Reply All</b>,\" or <b>forwarding</b> this email. Your action <b>will be lost</b> and not recorded if you do not use the buttons above.</p></blockquote>\r\n<hr>\r\n<p><b>Change Request Information:</b></p>\r\n<ul>\r\n<li><p><b>CR Subject:</b>&nbsp;{{cr_title}}</p></li>\r\n<li><p><b>CR Description:</b>&nbsp;{{cr_description}}</p></li>\r\n<li><p><b>Requester:</b> {{requester_name}}</p></li>\r\n</ul>\r\n<p>Thank you in advance for your prompt action.</p><hr><p><i><span style=\"font-weight: 600;\">Note:</span>&nbsp;This is an automated message sent by the IT TMS System.</i></p><p><span style=\"font-weight: 600;\">Best regards,</span><br><span style=\"font-weight: 600;\">TMS</span></p>', '[\"cr_no\", \"division_manager_name\", \"cr_title\", \"cr_description\", \"requester_name\", \"cr_link\", \"approve_link\", \"reject_link\", \"system_link\"]', 1, '2025-10-30 20:42:59', '2025-11-13 11:40:09');
INSERT INTO `notification_templates` VALUES (3, 'CR Created - Notify Division Manager (Promo)', '[TMS] Promo #{{cr_no}}', 'Dear {{division_manager_name}},<br><br>Promo with ID <strong>#<a href=\"{{cr_link}}\">{{cr_no}}</a></strong> has been created and is currently <ul><li><strong>Promo Subject:</strong> {{cr_title}}</li><li><strong>Promo Description:</strong> {{cr_description}}</li><li><strong>Requester:</strong> {{requester_name}}</li><li><strong>Reference:</strong> Promo ID #{{cr_no}}</li></ul><div><hr><p><i><span style=\"font-weight: 600;\">Note:</span>&nbsp;This is an automated message sent by the IT TMS System.</i></p><p><span style=\"font-weight: 600;\">Best regards,</span><br><span style=\"font-weight: 600;\">TMS</span></p></div>', '[\"cr_no\", \"division_manager_name\", \"cr_title\", \"cr_description\", \"requester_name\", \"cr_link\"]', 1, '2025-10-30 20:42:59', '2025-11-13 11:39:57');
INSERT INTO `notification_templates` VALUES (4, 'CR Status Updated - Notify Requester', '[TMS] CR #{{cr_no}} status has been changed', '<p>Dear {{first_name}},</p><p>The status of Change Request (CR) #{{cr_no}} has been updated from <b>{{old_status}}</b> to <b>{{new_status}}</b>.</p><p><b>CR Title:</b> {{cr_title}}</p><p>You can review it here: <a href=\"{{cr_link}}\"><b>View CR #{{cr_no}}</b></a></p><hr><p><i><b>Note:</b> This is an automated message sent by the IT TMS System.</i></p><p><b>Best regards,</b><br><b>TMS</b></p>', '[\"cr_no\", \"first_name\", \"old_status\", \"new_status\", \"cr_title\", \"cr_link\"]', 1, '2025-10-30 20:44:12', '2025-11-13 11:39:41');
INSERT INTO `notification_templates` VALUES (5, 'CR Assignment', '[TMS] CR #{{cr_no}} Assigned to You', '<p>Dear {{first_name}},</p><p>Change Request (CR) #{{cr_no}} has been <b>assigned</b> to you for your action.</p><p><b>CR Title:</b> {{cr_title}}<br><b>CR Status:</b> {{current_status}}</p><p>You can review it here: <a href=\"{{cr_link}}\"><b>View CR #{{cr_no}}</b></a></p><hr><p><i><b>Note:</b> This is an automated message sent by the IT TMS System.</i></p><p><b>Best regards,</b><br><b>TMS</b></p>', '[\"cr_no\", \"group_name\", \"old_status\", \"new_status\", \"cr_title\", \"cr_link\"]', 1, '2025-10-30 11:38:53', '2025-11-12 14:52:52');
